401	// Check for whether the tile shape is aligned (Default: 32Bytes).
402	template <class L1TileShape, class L0TileShape, class ElementA, class ElementB, uint32_t _aligned = 32>
403	struct TileShapeAlignChecker {
404	    static constexpr uint32_t _ALIGN = _aligned * 8;
405	
406	    static_assert(L1TileShape::M * SizeOfBits<ElementA>::value % _ALIGN == 0, "L1TileShape::M is not aligned.");
407	    static_assert(L0TileShape::M * SizeOfBits<ElementA>::value % _ALIGN == 0, "L0TileShape::M is not aligned.");
408	    static_assert(L1TileShape::K * SizeOfBits<ElementA>::value % _ALIGN == 0, "L1TileShape::K is not aligned.");
409	    static_assert(L1TileShape::K * SizeOfBits<ElementB>::value % _ALIGN == 0, "L1TileShape::K is not aligned.");
410	    static_assert(L0TileShape::K * SizeOfBits<ElementA>::value % _ALIGN == 0, "L0TileShape::K is not aligned.");
411	    static_assert(L0TileShape::K * SizeOfBits<ElementB>::value % _ALIGN == 0, "L0TileShape::K is not aligned.");
412	    static_assert(L1TileShape::N * SizeOfBits<ElementB>::value % _ALIGN == 0, "L1TileShape::N is not aligned.");
413	    static_assert(L0TileShape::N * SizeOfBits<ElementB>::value % _ALIGN == 0, "L0TileShape::N is not aligned.");
414	};
